import{_ as a,c as r,o as t,ag as o}from"./chunks/framework.Vyheyqg9.js";const m=JSON.parse('{"title":"Practice: Can you provide some examples for accessibility?","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/a11y/Can_you_provide_some_examples_for_a11y.md","filePath":"practice/frontend/a11y/Can_you_provide_some_examples_for_a11y.md"}'),s={name:"practice/frontend/a11y/Can_you_provide_some_examples_for_a11y.md"};function n(i,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="practice-can-you-provide-some-examples-for-accessibility" tabindex="-1">Practice: Can you provide some examples for accessibility? <a class="header-anchor" href="#practice-can-you-provide-some-examples-for-accessibility" aria-label="Permalink to “Practice: Can you provide some examples for accessibility?”">​</a></h1><p><strong>Status: outstanding learner practice.</strong> Author checks do not complete these requirements.</p><p>Prerequisite: study the <a href="./../../../senior_growth/A11y/Can_you_provide_some_examples_for_a11y.html">worked lesson</a> and its linked foundations. Apply these focused cases to <a href="./../../frontend-project.html">P-328/P-329/P-330</a>; retain only the cases relevant to the chosen increment.</p><h2 id="scope-and-observable-criteria" tabindex="-1"><span class="hub-section-number">1 </span>Scope and observable criteria <a class="header-anchor" href="#scope-and-observable-criteria" aria-label="Permalink to “1 Scope and observable criteria”">​</a></h2><p><strong>Exercise — complete contact flow:</strong> implement this example with visible focus and responsive dialog sizing. Acceptance: the dialog&#39;s name and input label are exposed; Tab/Shift+Tab stay within the modal; Escape/Cancel restore focus; background cannot be operated; invalid submission focuses a readable summary and associates the error; valid submission announces the truthful outcome; zoom400% and long text do not obscure essential controls. Verify with a real screen reader/browser pair and record results. Add a server adapter only after distinguishing validation success from saving success. This exercise remains learner practice.</p><p><strong>Image exercise:</strong> supply two sizes/crops and implement this in the matching layout. Acceptance: record viewport/density/currentSrc/transfer size; narrow crop and wide image communicate equivalent meaning; dimensions prevent avoidable shift; slow network does not delay the hero through lazy loading; meaningful alt and keyboard-linked-image names are verified. Do not infer selection from filename or DOM src alone.</p><p><strong>Media exercise:</strong> create a short recording, valid captions and a descriptive transcript, then test failed-media and keyboard paths. Acceptance: captions accurately synchronize and include meaningful sounds; essential visual actions are described; native controls have usable names/focus; no forced autoplay; alternatives remain available if video fails. Record the actual reader/browser checks. These assets/exercises are not claimed as completed by the learner.</p><h2 id="evidence" tabindex="-1"><span class="hub-section-number">2 </span>Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to “2 Evidence”">​</a></h2><p>Record source revision, runtime/browser versions, expected versus observed result, one reproduced failure, correction and retest. Include exact commands or input sequence and artifacts. Mark unperformed keyboard, screen-reader, zoom, device and integration checks explicitly. Never record a supplied example as your completed practice.</p><h2 id="manual-evidence-record-fill-with-actual-observations" tabindex="-1"><span class="hub-section-number">3 </span>Manual evidence record: fill with actual observations <a class="header-anchor" href="#manual-evidence-record-fill-with-actual-observations" aria-label="Permalink to “3 Manual evidence record: fill with actual observations”">​</a></h2><table tabindex="0"><thead><tr><th>Flow</th><th>Expected behavior</th><th>Required evidence</th></tr></thead><tbody><tr><td>Open modal</td><td>Named dialog, intentional initial focus, background unavailable</td><td>Browser/OS/reader versions, focus/announcement observation</td></tr><tr><td>Keyboard close</td><td>Tab containment, Escape/Cancel, logical restore/fallback</td><td>Keyboard trace and removed-trigger case</td></tr><tr><td>Invalid local/server form</td><td>Summary focused, links focus fields, errors described</td><td>Actual announcement/reading order; no duplicate assertive announcements</td></tr><tr><td>Slow save/cancel/error</td><td>Truthful status, usable controls, draft retained, no false success</td><td>Adapter/HTTP result plus keyboard/reader observation</td></tr><tr><td>Confirmed success</td><td>Close only after persistence; surviving region announces result</td><td>Real committed result and observed announcement</td></tr><tr><td>Zoom/reflow/motion</td><td>Essential controls/errors visible/operable, no blocked focus</td><td>Narrow/400%/preferences test artifacts</td></tr></tbody></table><p>Every evidence cell is <strong>unperformed learner practice</strong>, not a pass. Automated DOM/name/role checks can detect some defects but cannot substitute for these observations. Record expected versus actual, severity, correction/retest and residual support limits. Avoid claiming an entire product conforms because this fixture works in one reader/browser pair.</p><p>Official references checked2026-10-21: <a href="https://www.w3.org/WAI/tutorials/forms/notifications/" target="_blank" rel="noreferrer">WAI form notifications</a>, <a href="https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/" target="_blank" rel="noreferrer">WAI modal pattern</a>, <a href="https://www.w3.org/TR/accname-1.2/" target="_blank" rel="noreferrer">AccName1.2 draft</a>, <a href="https://www.w3.org/TR/WCAG22/" target="_blank" rel="noreferrer">WCAG2.2</a>. Accessible names/descriptions and announcement timing need the declared platform matrix; syntax validation supplies no manual pass.</p>',13)])])}const f=a(s,[["render",n]]);export{m as __pageData,f as default};
